--

CREATE TABLE `profielen` (
  `id` int NOT NULL,
  `gebruiker_id` int NOT NULL,
  `voornaam` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
